# Inventário de cobertura e lacunas dos dados embutidos / Coverage and gap
# inventory of the bundled datasets (issue #8).
#
# Uso / usage, a partir da raiz do pacote / from the package root:
#   Rscript tools/coverage-inventory.R
# Gera / writes planning/inventario-cobertura-tabelas.md (não editar à mão /
# do not edit by hand). O texto analítico fica em planning/inventario-cobertura.md.

suppressMessages(devtools::load_all(quiet = TRUE))

out_file <- file.path("planning", "inventario-cobertura-tabelas.md")

datasets <- c(
  "enrollment_kang_fgv", "enrollment_tertiary", "schooling_kang_fgv",
  "expenditure_kang_fgv", "progression_kang_fgv", "lee_lee_2016"
)

# Compacta anos em intervalos: 1990:1995, 1998 -> "1990–1995, 1998".
compress_years <- function(y, step = 1) {
  y <- sort(unique(y))
  if (length(y) == 0) return("")
  runs <- split(y, cumsum(c(1, diff(y) != step)))
  suffix <- if (step == 1) "" else paste0(" (a cada / every ", step, ")")
  paste(vapply(runs, function(r) {
    if (length(r) == 1) as.character(r) else paste0(r[1], "–", r[length(r)], suffix)
  }, character(1)), collapse = ", ")
}

missing_years <- function(y, step = 1) {
  y <- sort(unique(y))
  setdiff(seq(min(y), max(y), by = step), y)
}

col_or_total <- function(d, col) {
  v <- if (col %in% names(d)) as.character(d[[col]]) else rep("total", nrow(d))
  v[is.na(v) | v == ""] <- "—"
  v
}

is_derived <- function(d) {
  if ("is_derived" %in% names(d)) d$is_derived %in% TRUE else rep(FALSE, nrow(d))
}

md_table <- function(df) {
  df[] <- lapply(df, function(x) gsub("|", "\\|", as.character(x), fixed = TRUE))
  header <- paste0("| ", paste(names(df), collapse = " | "), " |")
  sep <- paste0("|", paste(rep("---", ncol(df)), collapse = "|"), "|")
  rows <- apply(df, 1, function(r) paste0("| ", paste(r, collapse = " | "), " |"))
  c(header, sep, rows, "")
}

# Agrupa e resume anos por combinação de colunas.
year_coverage <- function(d, by, step = 1) {
  key <- do.call(paste, c(lapply(by, function(b) col_or_total(d, b)), sep = "\r"))
  groups <- split(d$year, key)
  parts <- strsplit(names(groups), "\r", fixed = TRUE)
  res <- as.data.frame(do.call(rbind, parts), stringsAsFactors = FALSE)
  names(res) <- by
  res$n_anos <- vapply(groups, function(y) length(unique(y)), integer(1))
  res$anos <- vapply(groups, compress_years, character(1), step = step)
  res$lacunas <- vapply(groups, function(y) compress_years(missing_years(y, step), step), character(1))
  res[do.call(order, unname(res[by])), , drop = FALSE]
}

lines <- c(
