# 1. Resumo por conjunto / per-dataset summary ------------------------------
summary_df <- do.call(rbind, lapply(datasets, function(n) {
  d <- get(n)
  data.frame(
    conjunto = paste0("`", n, "`"),
    linhas = nrow(d),
    anos = paste0(min(d$year), "–", max(d$year)),
    n_anos = length(unique(d$year)),
    geo = paste(sort(unique(as.character(d$geo_level))), collapse = ", "),
    n_geo = length(unique(d$geo_code)),
    indicadores = paste(sort(unique(as.character(d$indicator))), collapse = ", "),
    fontes = length(unique(d$source)),
    derivadas = sum(is_derived(d)),
    stringsAsFactors = FALSE
  )
}))
lines <- c(lines, "## 1. Resumo por conjunto / Per-dataset summary", "",
           md_table(summary_df))

