# 3. Superior / enrollment_tertiary -----------------------------------------
et <- enrollment_tertiary
et_obs <- et[!is_derived(et), ]
lines <- c(lines,
  "## 3. `enrollment_tertiary`", "",
  "### 3a. Fonte × modalidade (linhas observadas) / source × modality (observed rows)", "",
  md_table(year_coverage(et_obs, c("source", "modality"))),
  "### 3b. Rede administrativa × fonte (observadas) / network × source (observed)", "",
  md_table(year_coverage(et_obs, c("network", "source"))),
  "### 3c. Organização acadêmica × fonte (observadas) / academic organization × source (observed)", "",
  md_table(year_coverage(et_obs, c("institution_type", "source"))),
  "### 3d. Linhas derivadas / derived rows", "",
  md_table(year_coverage(et[is_derived(et), ], c("source", "modality", "network")))
)

# Totais nacionais: sobreposição de fontes / national totals: source overlap
tot <- et_obs[et_obs$network == "total" & et_obs$institution_type == "total" &
                et_obs$modality %in% c("total", "presencial"), ]
ov <- do.call(rbind, lapply(split(tot, paste(tot$year, tot$modality)), function(g) {
  if (length(unique(g$source)) < 2) return(NULL)
  data.frame(
    ano = g$year[1], modalidade = as.character(g$modality[1]),
    fontes = paste(sort(unique(g$source)), collapse = ", "),
    min = min(g$value), max = max(g$value),
    dif_pct = round(100 * (max(g$value) - min(g$value)) / min(g$value), 2),
    stringsAsFactors = FALSE
  )
}))
ov <- ov[order(ov$modalidade, ov$ano), ]
lines <- c(lines,
  "### 3e. Sobreposição de fontes nos totais nacionais / source overlap in national totals", "",
  "Anos com mais de uma fonte para o mesmo total (rede, organização = total). `dif_pct` = (máx − mín) / mín. / Years with more than one source for the same total.", "",
  md_table(ov)
)

# Quebras: variação anual > 25% no total por fonte / breaks: >25% annual change
brk <- do.call(rbind, lapply(split(tot, paste(tot$source, tot$modality)), function(g) {
  g <- g[order(g$year), ]
  if (nrow(g) < 2) return(NULL)
  ch <- g$value[-1] / g$value[-nrow(g)] - 1
  gap <- diff(g$year)
  i <- which(abs(ch) > 0.25 & gap == 1)
  if (!length(i)) return(NULL)
  data.frame(fonte = g$source[i + 1], modalidade = as.character(g$modality[i + 1]),
             de = g$year[i], para = g$year[i + 1],
             variacao_pct = round(100 * ch[i], 1), stringsAsFactors = FALSE)
}))
lines <- c(lines,
  "### 3f. Variações anuais acima de 25% no total (anos consecutivos) / annual changes above 25% in totals (consecutive years)", "",
  if (is.null(brk)) c("Nenhuma / none.", "") else md_table(brk)
)

# Comparação com a série superior de Kang, Paese & Felix (enrollment_kang_fgv)
# / comparison with the Kang, Paese & Felix tertiary series
kpf <- ek[ek$level == "superior" & ek$indicator == "enrollment_count" &
            ek$geo_level == "BR" & ek$dim_race == "total", c("year", "value")]
tt <- et[et$network == "total" & et$institution_type == "total" &
           et$modality == "total", c("year", "value", "source")]
cmp <- merge(kpf, tt, by = "year", suffixes = c("_kpf", "_terciaria"))
cmp$dif_pct <- round(100 * (cmp$value_terciaria - cmp$value_kpf) / cmp$value_kpf, 2)
cmp_sum <- do.call(rbind, lapply(split(cmp, cmp$source), function(g) {
  data.frame(fonte_terciaria = g$source[1], n_anos = nrow(g),
             anos = compress_years(g$year),
             anos_iguais = sum(abs(g$dif_pct) < 0.005),
             dif_pct_min = min(g$dif_pct), dif_pct_max = max(g$dif_pct),
             stringsAsFactors = FALSE)
}))
lines <- c(lines,
  "### 3g. Total do superior: `enrollment_tertiary` × Kang, Paese & Felix (`enrollment_kang_fgv`) / tertiary total vs Kang, Paese & Felix", "",
  "`dif_pct` = (terciária − KPF) / KPF. / `dif_pct` = (tertiary − KPF) / KPF.", "",
  md_table(cmp_sum)
)

